window.CLORE_ASSETS = {"clore-templates/tokens.css":"/* CLORE v1.5 canonical tokens for 3D Film Parts.\n   Built from the confirmed 3D Film Parts design system token set (v1.2, June 2026)\n   and extended into the --clore-* namespace used by CLORE Studio templates.\n   Supersedes the v1.3 baseline reconstruction. All v1.3 names are preserved.\n   Rules carried in from the brand spec:\n   - Title colour adapts to background: ink on light, white on dark or red.\n   - Warm Gold replaces Signal Red as the eyebrow accent on dark grounds only.\n   - Campaign posts use centred layout, product posts use left-aligned layout.\n   - Never use em dashes anywhere. */\n\n:root {\n  /* Color, brand */\n  --clore-signal-red: #E8231F;\n  --clore-warm-gold: #CBB88F;   /* eyebrow accent on dark grounds only */\n\n  /* Color, ink and text */\n  --clore-ink: #111111;\n  --clore-black: #000000;\n  --clore-white: #FFFFFF;\n  --clore-grey: #8A8A8A;\n  --clore-muted: #54534F;        /* secondary copy on light */\n  --clore-faint: #8A8A86;        /* tertiary meta on light */\n  --clore-muted-dark: #9B988F;   /* secondary copy on dark */\n  --clore-faint-dark: #7D7A72;   /* tertiary meta on dark */\n\n  /* Color, grounds (one flat ground per post) */\n  --clore-paper: #F2EFE8;        /* editorial light */\n  --clore-surface: #FFFFFF;      /* studio clean, cards */\n  --clore-dark: #121211;         /* editorial dark */\n  --clore-cinematic: #0E0E0E;    /* banner and sale near-black */\n\n  /* Color, hairlines */\n  --clore-hairline-light: #D3CFC3;\n  --clore-hairline-dark: #2C2B28;\n\n  /* Type */\n  --clore-font-display: 'Archivo Black', 'Arial Black', sans-serif;\n  --clore-font-mono: 'JetBrains Mono', 'Courier New', monospace;\n\n  /* Type, tracking */\n  --clore-track-head: -0.035em;  /* headlines, tight */\n  --clore-track-eyebrow: 0.18em; /* eyebrow */\n  --clore-track-label: 0.12em;   /* CTA and labels, uppercase */\n  --clore-track-spec: 0.07em;    /* spec and descriptor */\n  --clore-track-meta: 0.05em;    /* handle and meta */\n\n  /* Type, line height */\n  --clore-lh-head: 0.92;         /* headline range 0.86 to 0.95 */\n  --clore-lh-head-tight: 0.86;   /* statement scale */\n\n  /* Spacing, safe margins (1080 canvas reference) */\n  --clore-safe-social: 88px;\n  --clore-safe-social-sm: 48px;\n  --clore-clear-top: 250px;      /* story, keep clear of platform UI */\n  --clore-clear-bottom: 220px;\n\n  /* Radii */\n  --clore-radius-chip: 6px;\n  --clore-radius-code: 8px;\n  --clore-radius-card: 16px;\n  --clore-radius-card-lg: 24px;\n  --clore-radius-pill: 999px;\n\n  /* Elevation */\n  --clore-card-shadow: 0 22px 48px rgba(20, 20, 20, 0.30);\n\n  /* Motifs */\n  --clore-ebar-w: 46px;          /* eyebrow accent rule */\n  --clore-ebar-h: 3px;\n  --clore-clapper-w: 4px;        /* vertical Signal Red seam */\n\n  /* Clapper Stripe motif: alternating ink/white diagonal bands */\n  --clore-stripe: repeating-linear-gradient(\n    -45deg,\n    var(--clore-ink) 0px,\n    var(--clore-ink) 26px,\n    var(--clore-white) 26px,\n    var(--clore-white) 52px\n  );\n\n  /* Frame */\n  --clore-frame-width: 4px;\n  --clore-frame-width-story: 6px;\n}\n","clore-templates/T02-editorial.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T02 Editorial: product post on the paper ground.\n     Layout follows the approved editorial references: centred logo, red eyebrow,\n     rounded photo card with a circle badge, left-aligned ink headline, CTA footer.\n     LOGO: pass the INK logo variant (light ground). No CSS filters.\n     BADGE fills the red circle badge on the photo card; empty badge hides it.\n     PRICE may be empty; it hides cleanly. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-paper); }\n\n  .card {\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    background: var(--clore-paper);\n    overflow: hidden;\n    padding: 56px 64px 52px;\n  }\n\n  /* Format dimensions */\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; padding: 96px 72px 88px; }\n  .format-webbanner .card { width: 1600px; height: 600px; flex-direction: row; padding: 0; }\n  .format-emailbanner .card { width: 1200px; height: 400px; flex-direction: row; padding: 0; }\n\n  .top {\n    flex: 0 0 auto;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 20px;\n    margin-bottom: 40px;\n  }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: uppercase;\n    color: var(--clore-signal-red);\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  .photo-card {\n    position: relative;\n    flex: 1 1 auto;\n    min-height: 0;\n    border-radius: var(--clore-radius-card-lg);\n    overflow: hidden;\n    background: var(--clore-surface);\n    box-shadow: var(--clore-card-shadow);\n  }\n  .photo-card img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n  }\n\n  .circle-badge {\n    position: absolute;\n    top: 36px;\n    right: 36px;\n    width: 148px;\n    height: 148px;\n    border-radius: var(--clore-radius-pill);\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 20px;\n    line-height: 1.35;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    padding: 18px;\n  }\n  .circle-badge:empty { display: none; }\n\n  .panel { flex: 0 0 auto; margin-top: 44px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 66px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 84px; -webkit-line-clamp: 3; }\n  .format-portrait h1 { -webkit-line-clamp: 3; }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 24px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-ink);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .footer {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    border-top: 2px solid var(--clore-hairline-light);\n    margin-top: 32px;\n    padding-top: 26px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint);\n  }\n\n  /* Banner variants: photo card left, text column right */\n  .format-webbanner .top, .format-emailbanner .top {\n    display: none;\n  }\n  .format-webbanner .photo-card, .format-emailbanner .photo-card {\n    flex: 0 0 44%;\n    border-radius: 0;\n    box-shadow: none;\n  }\n  .format-webbanner .panel, .format-emailbanner .panel {\n    flex: 1 1 auto;\n    margin: 0;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    padding: 48px 64px;\n    min-width: 0;\n  }\n  .format-webbanner .circle-badge { width: 124px; height: 124px; font-size: 17px; top: 28px; right: 28px; }\n  .format-emailbanner .circle-badge { width: 96px; height: 96px; font-size: 14px; top: 20px; right: 20px; padding: 10px; }\n  .banner-head { display: none; }\n  .format-webbanner .banner-head, .format-emailbanner .banner-head {\n    display: flex;\n    align-items: center;\n    gap: 24px;\n    margin-bottom: 26px;\n  }\n  .banner-head .logo { height: 40px; }\n  .format-emailbanner .banner-head { margin-bottom: 16px; }\n  .format-emailbanner .banner-head .logo { height: 32px; }\n  .format-webbanner .banner-head .eyebrow { font-size: 20px; }\n  .format-emailbanner .banner-head .eyebrow { font-size: 16px; }\n  .format-webbanner h1 { font-size: 56px; -webkit-line-clamp: 2; }\n  .format-emailbanner h1 { font-size: 40px; -webkit-line-clamp: 2; }\n  .format-webbanner .price { font-size: 32px; }\n  .format-emailbanner .price { font-size: 26px; }\n  .format-webbanner .meta { margin-top: 18px; }\n  .format-emailbanner .meta { margin-top: 12px; }\n  .format-webbanner .footer { margin-top: 22px; padding-top: 18px; }\n  .format-emailbanner .footer { margin-top: 16px; padding-top: 14px; }\n  .format-webbanner .cta { font-size: 22px; }\n  .format-emailbanner .cta { font-size: 17px; }\n  .format-webbanner .handle { font-size: 18px; }\n  .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n    </div>\n    <div class=\"photo-card\">\n      <img src=\"{{IMAGE}}\" alt=\"\">\n      <div class=\"circle-badge\">{{BADGE}}</div>\n    </div>\n    <div class=\"panel\">\n      <div class=\"banner-head\">\n        <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n        <div class=\"eyebrow\">{{EYEBROW}}</div>\n      </div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"footer\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T05A-editorial-light.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T05A Editorial Light: full-bleed product hero with a light scrim,\n     left-aligned type block, red eyebrow, red accent rule, CTA row.\n     Built from approved reference 05 (editorial story), redesigned per format.\n     LOGO: pass the INK logo variant (light ground). No CSS filters.\n     BADGE fills the red circle badge top right; empty badge hides it.\n     PRICE may be empty; it hides cleanly. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-paper); }\n\n  .card {\n    position: relative;\n    background: var(--clore-paper);\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; }\n  .format-webbanner .card { width: 1600px; height: 600px; }\n  .format-emailbanner .card { width: 1200px; height: 400px; }\n\n  .hero {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n  .scrim {\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(180deg,\n      rgba(242, 239, 232, 0) 38%,\n      rgba(242, 239, 232, 0.82) 62%,\n      var(--clore-paper) 82%);\n  }\n\n  .top {\n    position: absolute;\n    top: 56px;\n    left: 64px;\n    right: 64px;\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n  }\n  .format-story .top { top: 72px; left: 72px; right: 72px; }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .circle-badge {\n    width: 148px;\n    height: 148px;\n    border-radius: var(--clore-radius-pill);\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 20px;\n    line-height: 1.35;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    padding: 18px;\n  }\n  .circle-badge:empty { display: none; }\n\n  .content {\n    position: absolute;\n    left: 64px;\n    right: 64px;\n    bottom: 52px;\n  }\n  .format-story .content { left: 72px; right: 72px; bottom: 96px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: lowercase;\n    color: var(--clore-signal-red);\n    margin-bottom: 20px;\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 76px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 96px; }\n  .format-square h1 { font-size: 64px; -webkit-line-clamp: 2; }\n\n  .rule {\n    width: var(--clore-ebar-w);\n    height: var(--clore-ebar-h);\n    background: var(--clore-signal-red);\n    margin-top: 26px;\n  }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 26px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-ink);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .cta-row {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-top: 30px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint);\n  }\n\n  /* Banner variants: text column left, photo bleeding in from the right */\n  .format-webbanner .hero, .format-emailbanner .hero {\n    left: 40%;\n    width: 60%;\n    inset: 0 0 0 40%;\n  }\n  .format-webbanner .scrim, .format-emailbanner .scrim {\n    background: linear-gradient(90deg,\n      var(--clore-paper) 40%,\n      rgba(242, 239, 232, 0.85) 52%,\n      rgba(242, 239, 232, 0) 72%);\n  }\n  .format-webbanner .top, .format-emailbanner .top { right: auto; }\n  .format-webbanner .top { top: 48px; left: 64px; }\n  .format-emailbanner .top { top: 36px; left: 48px; }\n  .format-emailbanner .logo { height: 36px; }\n  .format-webbanner .circle-badge, .format-emailbanner .circle-badge { display: none; }\n  .format-webbanner .content { left: 64px; right: 46%; bottom: 48px; }\n  .format-emailbanner .content { left: 48px; right: 44%; bottom: 36px; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 14px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 10px; }\n  .format-webbanner h1 { font-size: 56px; -webkit-line-clamp: 2; }\n  .format-emailbanner h1 { font-size: 38px; -webkit-line-clamp: 2; }\n  .format-webbanner .rule { margin-top: 18px; }\n  .format-emailbanner .rule { display: none; }\n  .format-webbanner .meta { margin-top: 18px; }\n  .format-emailbanner .meta { margin-top: 12px; }\n  .format-webbanner .price { font-size: 30px; }\n  .format-emailbanner .price { font-size: 24px; }\n  .format-webbanner .cta-row { margin-top: 20px; }\n  .format-emailbanner .cta-row { margin-top: 14px; }\n  .format-webbanner .cta { font-size: 21px; }\n  .format-emailbanner .cta { font-size: 16px; }\n  .format-webbanner .handle, .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <img class=\"hero\" src=\"{{IMAGE}}\" alt=\"\">\n    <div class=\"scrim\"></div>\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"circle-badge\">{{BADGE}}</div>\n    </div>\n    <div class=\"content\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"rule\"></div>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"cta-row\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T05B-editorial-dark.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T05B Editorial Dark: the dark-ground variant of T05A.\n     Full-bleed product hero over the editorial dark ground, white headline,\n     warm gold eyebrow (dark ground rule), red accent rule, CTA row.\n     LOGO: pass the WHITE logo variant (dark ground). No CSS filters.\n     BADGE fills the red circle badge top right; empty badge hides it.\n     PRICE may be empty; it hides cleanly. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-dark); }\n\n  .card {\n    position: relative;\n    background: var(--clore-dark);\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; }\n  .format-webbanner .card { width: 1600px; height: 600px; }\n  .format-emailbanner .card { width: 1200px; height: 400px; }\n\n  .hero {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n  .scrim {\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(180deg,\n      rgba(18, 18, 17, 0.12) 0%,\n      rgba(18, 18, 17, 0) 30%,\n      rgba(18, 18, 17, 0.82) 62%,\n      var(--clore-dark) 84%);\n  }\n\n  .top {\n    position: absolute;\n    top: 56px;\n    left: 64px;\n    right: 64px;\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n  }\n  .format-story .top { top: 72px; left: 72px; right: 72px; }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .circle-badge {\n    width: 148px;\n    height: 148px;\n    border-radius: var(--clore-radius-pill);\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 20px;\n    line-height: 1.35;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    padding: 18px;\n  }\n  .circle-badge:empty { display: none; }\n\n  .content {\n    position: absolute;\n    left: 64px;\n    right: 64px;\n    bottom: 52px;\n  }\n  .format-story .content { left: 72px; right: 72px; bottom: 96px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: lowercase;\n    color: var(--clore-warm-gold);\n    margin-bottom: 20px;\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 76px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-white);\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 96px; }\n  .format-square h1 { font-size: 64px; -webkit-line-clamp: 2; }\n\n  .rule {\n    width: var(--clore-ebar-w);\n    height: var(--clore-ebar-h);\n    background: var(--clore-signal-red);\n    margin-top: 26px;\n  }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 26px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-white);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .cta-row {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-top: 30px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-white);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint-dark);\n  }\n\n  /* Banner variants: text column left, photo bleeding in from the right */\n  .format-webbanner .hero, .format-emailbanner .hero {\n    inset: 0 0 0 40%;\n    width: 60%;\n  }\n  .format-webbanner .scrim, .format-emailbanner .scrim {\n    background: linear-gradient(90deg,\n      var(--clore-dark) 40%,\n      rgba(18, 18, 17, 0.85) 52%,\n      rgba(18, 18, 17, 0) 72%);\n  }\n  .format-webbanner .top, .format-emailbanner .top { right: auto; }\n  .format-webbanner .top { top: 48px; left: 64px; }\n  .format-emailbanner .top { top: 36px; left: 48px; }\n  .format-emailbanner .logo { height: 36px; }\n  .format-webbanner .circle-badge, .format-emailbanner .circle-badge { display: none; }\n  .format-webbanner .content { left: 64px; right: 46%; bottom: 48px; }\n  .format-emailbanner .content { left: 48px; right: 44%; bottom: 36px; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 14px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 10px; }\n  .format-webbanner h1 { font-size: 56px; -webkit-line-clamp: 2; }\n  .format-emailbanner h1 { font-size: 38px; -webkit-line-clamp: 2; }\n  .format-webbanner .rule { margin-top: 18px; }\n  .format-emailbanner .rule { display: none; }\n  .format-webbanner .meta { margin-top: 18px; }\n  .format-emailbanner .meta { margin-top: 12px; }\n  .format-webbanner .price { font-size: 30px; }\n  .format-emailbanner .price { font-size: 24px; }\n  .format-webbanner .cta-row { margin-top: 20px; }\n  .format-emailbanner .cta-row { margin-top: 14px; }\n  .format-webbanner .cta { font-size: 21px; }\n  .format-emailbanner .cta { font-size: 16px; }\n  .format-webbanner .handle, .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <img class=\"hero\" src=\"{{IMAGE}}\" alt=\"\">\n    <div class=\"scrim\"></div>\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"circle-badge\">{{BADGE}}</div>\n    </div>\n    <div class=\"content\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"rule\"></div>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"cta-row\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T10-dualsplit.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T10 Dual Split: two product angles separated by the vertical Signal Red\n     clapper seam, paper panel below with left-aligned type and CTA.\n     Built from approved reference 10 (dual split story), redesigned per format.\n     EXTRA SLOT: {{IMAGE2}} is the second angle, also a file:// URL.\n     If IMAGE2 is passed as an empty string the seam and right panel hide and\n     IMAGE fills the full width. LOGO: pass the INK logo variant.\n     BADGE fills the red pill top right; empty badge hides it. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-paper); }\n\n  .card {\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    background: var(--clore-paper);\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; }\n  .format-webbanner .card { width: 1600px; height: 600px; flex-direction: row; }\n  .format-emailbanner .card { width: 1200px; height: 400px; flex-direction: row; }\n\n  .split {\n    flex: 1 1 auto;\n    min-height: 0;\n    display: flex;\n  }\n  .half {\n    flex: 1 1 0;\n    min-width: 0;\n    background: var(--clore-surface);\n  }\n  .half img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n  }\n  .seam {\n    flex: 0 0 var(--clore-clapper-w);\n    background: var(--clore-signal-red);\n  }\n  /* Second angle missing: hide seam and right half, first image spans full */\n  .card:has(.img2[src=\"\"]) .seam,\n  .card:has(.img2[src=\"\"]) .half-2 { display: none; }\n\n  .top {\n    position: absolute;\n    top: 48px;\n    left: 56px;\n    right: 56px;\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n  }\n  .format-story .top { top: 64px; left: 64px; right: 64px; }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .pill {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 22px;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    padding: 12px 30px;\n    border-radius: var(--clore-radius-pill);\n  }\n  .pill:empty { display: none; }\n\n  .panel {\n    flex: 0 0 auto;\n    background: var(--clore-paper);\n    padding: 48px 56px 44px;\n  }\n  .format-story .panel { padding: 60px 64px 64px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: lowercase;\n    color: var(--clore-signal-red);\n    margin-bottom: 18px;\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 68px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 88px; -webkit-line-clamp: 3; }\n  .format-portrait h1 { -webkit-line-clamp: 3; }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 24px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-ink);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .cta-row {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    border-top: 2px solid var(--clore-hairline-light);\n    margin-top: 30px;\n    padding-top: 24px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint);\n  }\n\n  /* Banner variants: split left, panel right */\n  .format-webbanner .split, .format-emailbanner .split { flex: 0 0 52%; }\n  .format-webbanner .panel, .format-emailbanner .panel {\n    flex: 1 1 auto;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    min-width: 0;\n  }\n  .format-webbanner .panel { padding: 40px 56px; }\n  .format-emailbanner .panel { padding: 32px 44px; }\n  .format-webbanner .top, .format-emailbanner .top { display: none; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 12px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 10px; }\n  .format-webbanner h1 { font-size: 50px; }\n  .format-emailbanner h1 { font-size: 36px; }\n  .format-webbanner .meta { margin-top: 16px; }\n  .format-emailbanner .meta { margin-top: 12px; }\n  .format-webbanner .price { font-size: 30px; }\n  .format-emailbanner .price { font-size: 24px; }\n  .format-webbanner .cta-row { margin-top: 20px; padding-top: 16px; }\n  .format-emailbanner .cta-row { margin-top: 14px; padding-top: 12px; }\n  .format-webbanner .cta { font-size: 20px; }\n  .format-emailbanner .cta { font-size: 15px; }\n  .format-webbanner .handle, .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <div class=\"split\">\n      <div class=\"half half-1\"><img class=\"img1\" src=\"{{IMAGE}}\" alt=\"\"></div>\n      <div class=\"seam\"></div>\n      <div class=\"half half-2\"><img class=\"img2\" src=\"{{IMAGE2}}\" alt=\"\"></div>\n    </div>\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"pill\">{{BADGE}}</div>\n    </div>\n    <div class=\"panel\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"cta-row\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T11-herodetail.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T11 Hero Detail: full-bleed product hero on a light gradient ground with a\n     red-ringed circular detail inset, left-aligned type block and CTA row.\n     Built from approved reference 11 (hero detail square), redesigned per format.\n     EXTRA SLOT: {{IMAGE2}} is the detail crop shown inside the circle inset,\n     also a file:// URL. Empty IMAGE2 hides the whole inset.\n     BADGE is the caption under the detail circle, for example MOUNTING DETAIL.\n     Empty badge hides the caption. LOGO: pass the INK logo variant.\n     PRICE may be empty; it hides cleanly. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-white); }\n\n  .card {\n    position: relative;\n    background: linear-gradient(180deg, var(--clore-white) 0%, #EDEBE5 100%);\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; }\n  .format-webbanner .card { width: 1600px; height: 600px; }\n  .format-emailbanner .card { width: 1200px; height: 400px; }\n\n  .hero {\n    position: absolute;\n    inset: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n  }\n  .scrim {\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(180deg,\n      rgba(255, 255, 255, 0) 42%,\n      rgba(243, 241, 236, 0.85) 66%,\n      #EDEBE5 86%);\n  }\n\n  .top {\n    position: absolute;\n    top: 56px;\n    left: 64px;\n  }\n  .format-story .top { top: 72px; left: 72px; }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .inset {\n    position: absolute;\n    top: 96px;\n    right: 64px;\n    width: 300px;\n    text-align: center;\n  }\n  .format-story .inset { top: 128px; right: 72px; }\n  .ring {\n    width: 300px;\n    height: 300px;\n    border-radius: var(--clore-radius-pill);\n    border: 6px solid var(--clore-signal-red);\n    background: var(--clore-surface);\n    overflow: hidden;\n    box-shadow: var(--clore-card-shadow);\n  }\n  .ring img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n  }\n  .caption {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-signal-red);\n    margin-top: 22px;\n  }\n  .caption:empty { display: none; }\n  .card:has(.img2[src=\"\"]) .inset { display: none; }\n\n  .content {\n    position: absolute;\n    left: 64px;\n    right: 64px;\n    bottom: 52px;\n  }\n  .format-story .content { left: 72px; right: 72px; bottom: 96px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: lowercase;\n    color: var(--clore-signal-red);\n    margin-bottom: 20px;\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 76px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 96px; }\n  .format-square h1 { font-size: 64px; -webkit-line-clamp: 2; }\n\n  .rule {\n    width: var(--clore-ebar-w);\n    height: var(--clore-ebar-h);\n    background: var(--clore-signal-red);\n    margin-top: 26px;\n  }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 26px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-ink);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .cta-row {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-top: 30px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint);\n  }\n\n  /* Banner variants: type left, photo right, inset overlapping the photo */\n  .format-webbanner .hero, .format-emailbanner .hero {\n    inset: 0 0 0 42%;\n    width: 58%;\n  }\n  .format-webbanner .scrim, .format-emailbanner .scrim {\n    background: linear-gradient(90deg,\n      var(--clore-white) 42%,\n      rgba(255, 255, 255, 0.85) 54%,\n      rgba(255, 255, 255, 0) 74%);\n  }\n  .format-webbanner .top { top: 48px; left: 64px; }\n  .format-emailbanner .top { top: 36px; left: 48px; }\n  .format-emailbanner .logo { height: 36px; }\n  .format-webbanner .inset { top: auto; bottom: 56px; right: 56px; width: 180px; }\n  .format-webbanner .ring { width: 180px; height: 180px; border-width: 5px; }\n  .format-webbanner .caption { font-size: 15px; margin-top: 14px; }\n  .format-emailbanner .inset { display: none; }\n  .format-webbanner .content { left: 64px; right: 48%; bottom: 48px; }\n  .format-emailbanner .content { left: 48px; right: 46%; bottom: 36px; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 14px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 10px; }\n  .format-webbanner h1 { font-size: 56px; -webkit-line-clamp: 2; }\n  .format-emailbanner h1 { font-size: 38px; -webkit-line-clamp: 2; }\n  .format-webbanner .rule { margin-top: 18px; }\n  .format-emailbanner .rule { display: none; }\n  .format-webbanner .meta { margin-top: 18px; }\n  .format-emailbanner .meta { margin-top: 12px; }\n  .format-webbanner .price { font-size: 30px; }\n  .format-emailbanner .price { font-size: 24px; }\n  .format-webbanner .cta-row { margin-top: 20px; }\n  .format-emailbanner .cta-row { margin-top: 14px; }\n  .format-webbanner .cta { font-size: 21px; }\n  .format-emailbanner .cta { font-size: 16px; }\n  .format-webbanner .handle, .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <img class=\"hero\" src=\"{{IMAGE}}\" alt=\"\">\n    <div class=\"scrim\"></div>\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n    </div>\n    <div class=\"inset\">\n      <div class=\"ring\"><img class=\"img2\" src=\"{{IMAGE2}}\" alt=\"\"></div>\n      <div class=\"caption\">{{BADGE}}</div>\n    </div>\n    <div class=\"content\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"rule\"></div>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"cta-row\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T12-campaign.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T12 Campaign: the free-text template. Takes copy instead of a product.\n     Centred layout on the cinematic near-black ground with the red frame and\n     the clapper stripe, per the approved campaign references.\n     TITLE is the campaign headline, for example ALL OF IT.\n     EYEBROW is the kicker, for example EVERY SINGLE PRODUCT.\n     BADGE is the promo code rectangle, for example CODE EOFY15. Empty hides it.\n     PRICE is unused by this template and may be passed empty.\n     IMAGE is unused by this template. LOGO: pass the WHITE logo variant. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-cinematic); }\n\n  .card {\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    background: var(--clore-cinematic);\n    border: var(--clore-frame-width) solid var(--clore-signal-red);\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; border-width: var(--clore-frame-width-story); }\n  .format-webbanner .card { width: 1600px; height: 600px; }\n  .format-emailbanner .card { width: 1200px; height: 400px; }\n\n  .stripe {\n    height: 34px;\n    background: var(--clore-stripe);\n    flex: 0 0 auto;\n  }\n  .format-story .stripe { height: 52px; }\n  .format-webbanner .stripe, .format-emailbanner .stripe { height: 22px; }\n\n  .middle {\n    flex: 1 1 auto;\n    min-height: 0;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    padding: 48px 88px;\n  }\n  .format-emailbanner .middle { padding: 24px 64px; }\n\n  .logo { height: 56px; width: auto; margin-bottom: 56px; }\n  .format-story .logo { height: 68px; margin-bottom: 80px; }\n  .format-webbanner .logo { height: 44px; margin-bottom: 28px; }\n  .format-emailbanner .logo { height: 34px; margin-bottom: 18px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: uppercase;\n    color: var(--clore-signal-red);\n    margin-bottom: 26px;\n  }\n  .format-story .eyebrow { font-size: 32px; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 16px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 12px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 132px;\n    line-height: var(--clore-lh-head-tight);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-white);\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n    max-width: 100%;\n  }\n  .format-story h1 { font-size: 156px; }\n  .format-webbanner h1 { font-size: 88px; -webkit-line-clamp: 2; }\n  .format-emailbanner h1 { font-size: 60px; -webkit-line-clamp: 2; }\n\n  .code-badge {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 30px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    padding: 18px 40px;\n    border-radius: var(--clore-radius-code);\n    margin-top: 52px;\n  }\n  .code-badge:empty { display: none; }\n  .format-story .code-badge { font-size: 36px; margin-top: 72px; }\n  .format-webbanner .code-badge { font-size: 22px; padding: 12px 28px; margin-top: 28px; }\n  .format-emailbanner .code-badge { font-size: 18px; padding: 10px 22px; margin-top: 20px; }\n\n  .footer {\n    flex: 0 0 auto;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    border-top: 2px solid var(--clore-hairline-dark);\n    padding: 26px 0;\n  }\n  .format-story .footer { padding: 34px 0; }\n  .format-webbanner .footer, .format-emailbanner .footer { padding: 14px 0; }\n  .url {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-white);\n  }\n  .format-story .url { font-size: 32px; }\n  .format-webbanner .url { font-size: 19px; }\n  .format-emailbanner .url { font-size: 16px; }\n  .url .arrow { color: var(--clore-signal-red); }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <div class=\"stripe\"></div>\n    <div class=\"middle\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"code-badge\">{{BADGE}}</div>\n    </div>\n    <div class=\"footer\">\n      <span class=\"url\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/T13-cameratape.html":"<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<!-- T13 Camera Tape: paper ground with the brand's camera-tape frame art\n     (reel-frames/frame-h.png, generated + approved), taped polaroid product\n     card, editorial type block. Part of the CLORE design system tape family.\n     LOGO: pass the INK logo variant (light ground).\n     BADGE fills the red circle badge top right; empty badge hides it.\n     PRICE may be empty; it hides cleanly.\n     NOTE: the background image path is relative to clore-templates/.\n     TAPEBG slot: fill with reel-frames/frame-b|f|g|h|i.png (Camera Tape 1-5).\n     On dark grounds (frame-b, frame-g) pass the WHITE logo variant. -->\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/archivo-black/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/index.css\">\n<link rel=\"stylesheet\" href=\"../node_modules/@fontsource/jetbrains-mono/700.css\">\n<link rel=\"stylesheet\" href=\"tokens.css\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { background: var(--clore-paper); }\n\n  .card {\n    position: relative;\n    background: var(--clore-paper) url('{{TAPEBG}}') center / cover no-repeat;\n    overflow: hidden;\n  }\n\n  .format-square .card { width: 1080px; height: 1080px; }\n  .format-portrait .card { width: 1080px; height: 1350px; }\n  .format-story .card { width: 1080px; height: 1920px; }\n  .format-webbanner .card { width: 1600px; height: 600px; }\n  .format-emailbanner .card { width: 1200px; height: 400px; }\n\n  .top {\n    position: absolute;\n    top: 56px;\n    left: 64px;\n    right: 64px;\n    display: flex;\n    align-items: flex-start;\n    justify-content: space-between;\n    z-index: 3;\n  }\n  .format-story .top { top: 72px; left: 72px; right: 72px; }\n  .logo { height: 52px; width: auto; }\n  .format-story .logo { height: 64px; }\n\n  .circle-badge {\n    width: 148px;\n    height: 148px;\n    border-radius: var(--clore-radius-pill);\n    background: var(--clore-signal-red);\n    color: var(--clore-white);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-align: center;\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 20px;\n    line-height: 1.35;\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    padding: 18px;\n    transform: rotate(4deg);\n  }\n  .circle-badge:empty { display: none; }\n\n  /* Taped polaroid product card */\n  .photo-card {\n    position: absolute;\n    top: 200px;\n    left: 50%;\n    width: 620px;\n    height: 620px;\n    margin-left: -310px;\n    background: var(--clore-white);\n    padding: 22px 22px 64px;\n    box-shadow: 0 24px 60px rgba(20, 20, 20, 0.22);\n    transform: rotate(-2.5deg);\n    z-index: 1;\n  }\n  .format-story .photo-card { top: 300px; width: 700px; height: 700px; margin-left: -350px; }\n  .format-portrait .photo-card { top: 240px; }\n  .photo-card img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    display: block;\n  }\n  .tape {\n    position: absolute;\n    width: 220px;\n    height: 56px;\n    background: rgba(242, 239, 232, 0.92);\n    box-shadow: 0 4px 10px rgba(20, 20, 20, 0.14);\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 20px;\n    letter-spacing: 0.14em;\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 2;\n  }\n  .tape-tl { top: -20px; left: -46px; transform: rotate(-8deg); }\n  .tape-br { bottom: 30px; right: -52px; transform: rotate(6deg); background: var(--clore-signal-red); color: var(--clore-white); }\n\n  .content {\n    position: absolute;\n    left: 64px;\n    right: 64px;\n    bottom: 52px;\n    z-index: 3;\n    background: rgba(242, 239, 232, 0.9);\n    padding: 34px 38px 30px;\n  }\n  .format-story .content { left: 72px; right: 72px; bottom: 96px; }\n\n  .eyebrow {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 24px;\n    letter-spacing: var(--clore-track-eyebrow);\n    text-transform: lowercase;\n    color: var(--clore-signal-red);\n    margin-bottom: 18px;\n  }\n  .format-story .eyebrow { font-size: 28px; }\n\n  h1 {\n    font-family: var(--clore-font-display);\n    font-size: 64px;\n    line-height: var(--clore-lh-head);\n    letter-spacing: var(--clore-track-head);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    overflow: hidden;\n  }\n  .format-story h1 { font-size: 84px; -webkit-line-clamp: 3; }\n\n  .rule {\n    width: var(--clore-ebar-w);\n    height: var(--clore-ebar-h);\n    background: var(--clore-signal-red);\n    margin-top: 22px;\n  }\n\n  .meta { display: flex; align-items: center; gap: 28px; margin-top: 22px; }\n  .price {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 38px;\n    color: var(--clore-ink);\n  }\n  .price:empty { display: none; }\n  .format-story .price { font-size: 46px; }\n\n  .cta-row {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-top: 24px;\n  }\n  .cta {\n    font-family: var(--clore-font-mono);\n    font-weight: 700;\n    font-size: 26px;\n    letter-spacing: var(--clore-track-label);\n    text-transform: uppercase;\n    color: var(--clore-ink);\n  }\n  .format-story .cta { font-size: 30px; }\n  .arrow { color: var(--clore-signal-red); }\n  .handle {\n    font-family: var(--clore-font-mono);\n    font-weight: 400;\n    font-size: 22px;\n    letter-spacing: var(--clore-track-meta);\n    color: var(--clore-faint);\n  }\n\n  /* Banner variants: photo card right, text panel left */\n  .format-webbanner .photo-card, .format-emailbanner .photo-card {\n    left: auto;\n    margin-left: 0;\n  }\n  .format-webbanner .photo-card { top: 40px; right: 90px; width: 460px; height: 460px; padding: 16px 16px 44px; }\n  .format-emailbanner .photo-card { top: 30px; right: 70px; width: 300px; height: 300px; padding: 12px 12px 32px; }\n  .format-emailbanner .tape { width: 150px; height: 40px; font-size: 14px; }\n  .format-webbanner .tape { width: 180px; height: 48px; font-size: 17px; }\n  .format-webbanner .circle-badge, .format-emailbanner .circle-badge { display: none; }\n  .format-webbanner .top { top: 48px; left: 64px; right: auto; }\n  .format-emailbanner .top { top: 36px; left: 48px; right: auto; }\n  .format-emailbanner .logo { height: 36px; }\n  .format-webbanner .content { left: 64px; right: 46%; bottom: 48px; padding: 26px 30px 24px; }\n  .format-emailbanner .content { left: 48px; right: 42%; bottom: 32px; padding: 18px 22px 16px; }\n  .format-webbanner .eyebrow { font-size: 20px; margin-bottom: 12px; }\n  .format-emailbanner .eyebrow { font-size: 16px; margin-bottom: 8px; }\n  .format-webbanner h1 { font-size: 52px; }\n  .format-emailbanner h1 { font-size: 36px; }\n  .format-webbanner .rule { margin-top: 16px; }\n  .format-emailbanner .rule { display: none; }\n  .format-webbanner .meta { margin-top: 16px; }\n  .format-emailbanner .meta { margin-top: 10px; }\n  .format-webbanner .price { font-size: 30px; }\n  .format-emailbanner .price { font-size: 24px; }\n  .format-webbanner .cta-row { margin-top: 18px; }\n  .format-emailbanner .cta-row { margin-top: 12px; }\n  .format-webbanner .cta { font-size: 21px; }\n  .format-emailbanner .cta { font-size: 16px; }\n  .format-webbanner .handle, .format-emailbanner .handle { display: none; }\n</style>\n</head>\n<body class=\"format-{{FORMAT}}\">\n  <div class=\"card\">\n    <div class=\"top\">\n      <img class=\"logo\" src=\"{{LOGO}}\" alt=\"3D Film Parts\">\n      <div class=\"circle-badge\">{{BADGE}}</div>\n    </div>\n    <div class=\"photo-card\">\n      <div class=\"tape tape-tl\">CAM A</div>\n      <img src=\"{{IMAGE}}\" alt=\"\">\n      <div class=\"tape tape-br\">GOOD TAKE</div>\n    </div>\n    <div class=\"content\">\n      <div class=\"eyebrow\">{{EYEBROW}}</div>\n      <h1>{{TITLE}}</h1>\n      <div class=\"rule\"></div>\n      <div class=\"meta\"><span class=\"price\">{{PRICE}}</span></div>\n      <div class=\"cta-row\">\n        <span class=\"cta\">SHOP NOW <span class=\"arrow\">-&gt;</span> 3DFILMPARTS.COM</span>\n        <span class=\"handle\">@3dfilmparts</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>\n","clore-templates/preview-assets/logo-ink-transparent.png":"data:image/png;base64,","clore-templates/preview-assets/logo-white-transparent.png":"data:image/png;base64,","clore-templates/reel-frames/badge-new.png":"data:image/png;base64,","clore-templates/reel-frames/badge-hot.png":"data:image/png;base64,","clore-templates/reel-frames/badge-eyes.png":"data:image/png;base64,","clore-templates/reel-frames/frame-a.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-b.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-c.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-d.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-e.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-f.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-g.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-h.png":"data:image/jpeg;base64,","clore-templates/reel-frames/frame-i.png":"data:image/jpeg;base64,"};
